## Patterns to follow
Resolver (new `src/server/runhome.ts`) — exact names from the shared interfaces:
```ts
import { existsSync, realpathSync } from "node:fs";
import { readFile } from "node:fs/promises";
import path from "node:path";
import type { DataStore } from "./store.js";
import { PROJECTS_DIR, projectDirOf, type Project } from "./projects.js";
import { resolveWorkspace, type Workspace } from "./workspaces.js";

export const PROJECT_PREFIX = "project~";
export type RunHome =
  | { kind: "workspace"; id: string; path: string; workspace: Workspace }
  | { kind: "project"; id: string; path: string; project: Project };

/** `project~<id>` → the project folder (store record + `<workspacesDir>/.projects/<id>/.git`), else `resolveWorkspace`. */
export function resolveRunHome(workspacesDir: string, store: DataStore, id: string): RunHome | undefined {
  if (id.startsWith(PROJECT_PREFIX)) {
    const pid = id.slice(PROJECT_PREFIX.length);
    if (!/^[a-z0-9-]+$/.test(pid)) return undefined;
    const rec = store.project(pid);
    const dir = projectDirOf(workspacesDir, pid);
    if (!rec || !existsSync(path.join(dir, ".git"))) return undefined;
    return { kind: "project", id, path: dir, project: { id: pid, ...rec } };
  }
  const ws = resolveWorkspace(workspacesDir, id);
  return ws && { kind: "workspace", id: ws.id, path: ws.path, workspace: ws };
}
export const workspaceHome = (ws: Workspace): RunHome => ({ kind: "workspace", id: ws.id, path: ws.path, workspace: ws });
/** A `Workspace`-shaped view of a home for the code that takes one (summaries, sandbox paths): a project is `forge: "project"`, `rel: ".projects/<id>"`. */
export function homeAsWorkspace(home: RunHome): Workspace { … }
/** The project's repos in project.json order: link name + its workspace (matched by realpath of `<dir>/<repo.path>` against each workspace's realpath). Repos whose link or workspace is missing get `workspace: undefined`. */
export async function projectRepos(workspacesDir: string, home: Extract<RunHome, { kind: "project" }>): Promise<{ name: string; path: string; workspace?: Workspace }[]>
```
(`path.join` everywhere; compare `realpathSync.native` results; on Windows the links are junctions and `realpath` resolves them the same way.)

Run start today (routes/runs.ts:129–156) — keep this env and execa shape for the project start:
```ts
const env: NodeJS.ProcessEnv = { ...process.env, GRAPH_EXECUTION_HANDOFF: "detached", SSH_CONNECTION: "1", [RUN_ID_ENV]: runId };
const reviewersFile = reviewersFilePath(ctx.config.dataDir);
if (existsSync(reviewersFile)) env[REVIEWERS_ENV] = reviewersFile;
delete env.GM_PASSWORD;
for (const name of INTERNAL_ENV) delete env[name];
const cmd = engineCommand(ctx.config.graphExecutionBin, args);
const res = await execa(cmd.file, cmd.args, { cwd: ws.path, env, extendEnv: false, reject: false, all: true, stdin: "ignore", timeout: START_TIMEOUT_MS });
```
Error answers stay `{ error, exitCode?, output? }` with `lastLines(output, 20)`.

Fake engine for route tests (runoptions.test.ts:10–13 style), printing the suite line:
```ts
const FAKE_BIN = `import { writeFileSync } from "node:fs";
writeFileSync(new URL("./call.json", import.meta.url), JSON.stringify({ argv: process.argv.slice(2), cwd: process.cwd(), reviewers: process.env.GRAPH_EXECUTION_REVIEWERS ?? null }));
console.log("Started suite suite-20261113-120000-abcd in the background: http://127.0.0.1:1/");
`;
```

## How a test fakes a project run on disk (no engine)
```ts
const { app, cookie, config, store, cleanup } = await appWithLogin({ graphExecutionBin: fakeBin });
const g = (cwd: string, ...a: string[]) => execa("git", a, { cwd });
// two workspaces
for (const r of ["api", "web"]) { const d = path.join(config.workspacesDir, "github", "acme", r); await mkdir(d, { recursive: true }); await g(d, "init", "-q", "-b", "main"); }
// the project folder (what createProjectFolder in src/server/projects.ts makes; written by hand here)
const projDir = path.join(config.workspacesDir, ".projects", "billing");
await mkdir(path.join(projDir, "repos"), { recursive: true });
await g(projDir, "init", "-q", "-b", "main");
for (const r of ["api", "web"]) await symlink(path.join(config.workspacesDir, "github", "acme", r), path.join(projDir, "repos", r), process.platform === "win32" ? "junction" : "dir");
await writeFile(path.join(projDir, "project.json"), JSON.stringify({ name: "billing", repos: [{ name: "api", path: "repos/api" }, { name: "web", path: "repos/web" }] }));
await store.update((d) => { d.projects.billing = { /* or the store's project method in src/server/store.ts */ name: "billing", workspaces: ["github~acme~api", "github~acme~web"], createdAt: "2026-11-13T00:00:00.000Z" }; });
// the suite folder
const suiteId = "suite-20261113-120000-abcd";
const suiteDir = path.join(projDir, ".graph-execution", suiteId);
await mkdir(suiteDir, { recursive: true });
const repo = (name: string) => ({ name, path: path.join(config.workspacesDir, "github", "acme", name), startingCommit: "0".repeat(40), startBranch: "main" });
await writeFile(path.join(suiteDir, "suite.json"), JSON.stringify(suiteStateSchema.parse({
  suiteId, status: "applied", provider: "fake", concurrency: 2, startingCommit: "0".repeat(40), startBranch: "main", merge: true, humanReview: false,
  features: ["api", "web"].map((n, i) => ({ name: n, tasksDir: path.join(projDir, "tasks", n), prd: path.join(suiteDir, "specs", `${n}.md`), runId: `20261113-12000${i}-aaaa`, status: "done", repo: repo(n) })),
  integration: { merged: [] },
  project: { dir: projDir, name: "billing", contract: path.join(projDir, "contract.md") },
  repos: [{ ...repo("api"), applied: { files: 1, conflicts: [] } }, { ...repo("web"), applied: { files: 2, conflicts: [] } }],
  createdAt: "2026-11-13T12:00:00.000Z",
})));
```
`suiteStateSchema` comes from `graph-execution/api`; parsing it in the test makes a wrong shape fail loudly (two features keep it valid even if the schema still requires `min(2)`). To make the run **live**, start a tiny `http.createServer` on 127.0.0.1 port 0 (proxy.test.ts:23–45) and write `<suiteDir>/web.json` = `{ "url": "http://127.0.0.1:<port>/", "pid": process.pid }`. Skip symlink-dependent assertions with `describe.skipIf(process.platform === "win32")` only if a junction cannot be made; junctions need no admin rights, so try to keep them on.

## Step-by-step tasks
### CREATE `apps/graph-manager/src/server/runhome.ts`
- **IMPLEMENT**: `PROJECT_PREFIX`, `RunHome`, `resolveRunHome`, `workspaceHome`, `homeAsWorkspace`, `projectRepos` as above. `homeAsWorkspace` for a project returns `{ id: home.id, path: home.path, rel: \`${PROJECTS_DIR}/${pid}\`, forge: "project", fullPath: pid }` (rel with `/`, as `Workspace.rel` documents). `projectRepos` reads `project.json` with `JSON.parse` (tolerant: a missing/invalid file gives `[]`), resolves `path.resolve(home.path, repo.path)` and matches its `realpathSync.native` to `realpathSync.native(ws.path)` of each `resolveWorkspace(workspacesDir, wsId)` of `home.project.workspaces`.
- **GOTCHA**: `resolveWorkspace` refuses ids whose parts start with `.`, so `.projects` never resolves as a workspace — keep that; the project branch must come first. Only `github`/`gitlab` are forges, so `project~…` never clashes.
- **VALIDATE**: `npm run typecheck -w graph-manager`

### UPDATE `apps/graph-manager/src/server/runs.ts`
- **IMPLEMENT**: `RunSummary.project?: { id: string; name: string; repos: string[] }`. `SummaryExtras.project?: { id: string; name: string; repos: string[] }` (fallback repo names from `projectRepos`). Replace `readSuiteProvider` with `readSuite(dir)` returning the parsed `suiteStateSchema` data (or undefined); in `summarize`, for every entry of a project home set `summary.project = { id, name, repos: suite?.repos?.map(r => r.name) ?? extras.project.repos }` (plain runs in a project folder get the fallback list). Add `listHomeRuns(home: RunHome, workspacesDir, prs?, dataDir?)` that scans `home.path` and summarizes with `homeAsWorkspace(home)` (keep `listWorkspaceRuns(ws, …)` as a thin wrapper — `viewcache.ts:305` calls it). `listRuns(workspacesDir, prs?, dataDir?, projects?: Record<string, { name: string; workspaces: string[]; createdAt: string }>)`: workspaces as today plus every project whose folder resolves (build each home with the same rules as `resolveRunHome`; export a helper `projectHome(workspacesDir, id, rec)` from runhome.ts and use it in both). `runDetail(home: RunHome | Workspace, …)` and `runDirOf(home: { path: string }, runId)` accept a home (a `Workspace` still works: both have `id`/`path`). `landedChanges`/`taskLines` keep taking a `Workspace` (use `homeAsWorkspace`).
- **PATTERN**: `runs.ts:243–277` summarize; `viewUrlOf(home.id, entry.id)` gives `/runs/project~billing/<id>/view/`.
- **GOTCHA**: keep the summary shape of workspace runs byte-identical (`runs.test.ts:66–82` uses `toEqual`): never add `project: undefined`.
- **VALIDATE**: `npm test -w graph-manager -- src/server/runs.test.ts`

### UPDATE `apps/graph-manager/src/server/runoptions.ts`
- **IMPLEMENT**: add `"--project"` and `"--feature"` to `RESERVED_FLAGS`. Add `PROJECT_OPTIONS = ["humanReview", "merge", "model", "concurrency", "extraArgs"] as const` and `projectStartArgs({ provider, options })` = `["suite", "--project", ".", "--provider", provider, ...optionArgs(o), ...splitExtraArgs(o.extraArgs), "--web"]`. It throws `ExtraArgsError(\`options.${key} does not apply to a project run\`)` for any set option outside `PROJECT_OPTIONS` (the suite command takes only those; the others would be silently ignored).
- **VALIDATE**: `npm test -w graph-manager -- src/server/runoptions`

### UPDATE `apps/graph-manager/src/server/routes/runs.ts`
- **IMPLEMENT**: replace `workspaceOr404` with `homeOr404(ctx, id) = resolveRunHome(ctx.config.workspacesDir, ctx.store, id)`. `GET /api/runs`: no filter → `listRuns(…, ctx.store.get().projects)`; filter → `listHomeRuns(home, …)` (unknown → `[]`). `GET /api/runs/:ws/:runId` → `runDetail(home, …)` (404 `unknown workspace` stays the message for both kinds). `POST /api/runs/:ws`: workspace kind unchanged; project kind parses `projectStartBody = z.object({ provider: z.enum(PROVIDERS), concurrency: …optional(), options: runOptionsSchema.optional(), sandbox: z.boolean().optional() })` (tasksDir/spec are ignored: zod strips them), `sandbox: true` → 400 `{ error: "sandboxed project runs are not supported yet" }`, args = `projectStartArgs`, env as for a run (incl. `REVIEWERS_ENV` when `reviewersFilePath(dataDir)` exists, and `[RUN_ID_ENV]: \`suite-${newRunId()}\`` — harmless today, used once the engine honours it), `cwd: home.path`. Read the id with `/\b(?:Started suite|Suite) (suite-\S+?)(?: in the background)?(?::| started:)/`; prefer the printed id, else the one we set, and only if `isRunId`. Save `runDefaults[home.id] = { provider, tasksDir: "", spec: "", options }` and `rememberSandbox(ctx, home.id, false)`. Answer 201 `{ runId, viewUrl: viewUrlOf(home.id, runId) }`. `GET /api/workspaces/:id/run-defaults` uses `homeOr404`.
- **IMPLEMENT**: new `GET /api/projects/:id/inspect` (put it in `routes/inspect.ts`, exporting `inspectProject`) → `ProjectInspection = { id, name, contract: boolean, testPlan: boolean, repos: { name, workspaceId?: string, fullPath?: string, branch?: string, changes?: number, spec: boolean, taskFiles?: number }[] }` where `spec` = `specs/<name>.md` is a file, `taskFiles` = `countTaskFiles(<project>/tasks/<name>)` (undefined = no folder), branch/changes from the repo's workspace like `inspectWorkspace`. 404 `unknown project`.
- **GOTCHA**: `/api/projects/:id/...` must not collide with task-7 routes in `routes/projects.ts`; check that file and keep the path unique. `GET /api/workspaces/:id/settings` (routes/sandbox.ts:117) must answer for `project~<id>` too (read-only view of `workspaceSettings[home.id]`), so the drawer sees the saved switch; PUT stays workspace-only.
- **VALIDATE**: `npm test -w graph-manager -- src/server/routes`

### UPDATE `apps/graph-manager/src/server/proxy.ts` and `src/server/routes/resume.ts`
- **IMPLEMENT**: proxy line 84: `resolveRunHome(...)` then `runDirOf(home, runId)`. `resumeRun(ctx, home: RunHome, runId, opts)`: a suite in a **workspace** keeps the 400 `suites are resumed from a terminal`; a suite in a **project** reads `suite.json` (404 `unknown run` if invalid), 409 `the run is live` when `livePage(runDir)`, 409 `the run already finished (<status>)` for `applied`/`done`, 400 `sandboxed project runs are not supported yet` when `opts.sandbox` or `ctx.sandboxes?.recordOf(home.id, runId)`, else runs `engineCommand(bin, ["suite", "--resume", "--run", runId, "--web"])` in `home.path` with the same env as the run resume (lines 64–70). Routes use `resolveRunHome`; `sandbox/stop` uses `home.id`. `routes/internal.ts:129` passes `workspaceHome(ws)`.
- **VALIDATE**: `npm test -w graph-manager -- src/server/routes/resume.test.ts src/server/proxy.test.ts`

### UPDATE `apps/graph-manager/src/server/agent-requests.ts`, `tools/types.ts`, `tools/open-start-run.ts`, `routes/internal.ts`
- **IMPLEMENT**: `AgentRequest.projectId?: string`; `StartRunPrefill.tasksDir?`/`spec?` become optional. `ToolContext.project?: Extract<RunHome, { kind: "project" }>`: in internal.ts set it from `terminal.projectId` FIRST (via `resolveRunHome(…, \`project~${id}\`)`), else when `cwd` is `<workspacesDir>/.projects/<id>` or inside it. In a project terminal the agent may have `cd`'d into `repos/api` or into the real workspace path, so the cwd alone is not reliable: when `terminal.projectId` is set, `open_start_run` always targets the project, and `workspace` is left as `workspaceOf(cwd)` computes it (line 76). `open_start_run` input: `tasksDir`/`spec` become `.optional()` (describe them as "workspace terminals only"), new `project: z.boolean().optional().describe("Open the Start run form of the terminal's project (multi-repo suite); tasksDir and spec are ignored")`. If `tc.project` exists (or `i.project === true`): no project → error `this terminal is not on a graph-manager project`; else queue `{ kind: "start-run", terminalId, workspaceId: tc.project.id /* "project~<id>" */, projectId: tc.project.project.id, agent, terminalTitle, prefill: { provider?, options? } }` and answer `Opened the Start run form of project <name> in graph-manager. The user will review the options and start the run; do not start it yourself.` Otherwise (workspace terminal) both paths are required: missing → error `tasksDir and spec are required in a workspace terminal`.
- **GOTCHA**: update `open-start-run.test.ts` "is listed with tasksDir and spec required" (they are no longer in `required`; assert they are in `properties` instead).
- **VALIDATE**: `npm test -w graph-manager -- src/server/tools`

### UPDATE web: `src/web/types.ts`, `src/web/runs.ts`
- **IMPLEMENT**: `RunSummary.project?: { id: string; name: string; repos: string[] }`; `AgentRequest.projectId?: string`, prefill `tasksDir?`/`spec?`; `ProjectInspection` (as the server). In `runs.ts`: `isProjectId = (id) => id.startsWith("project~")` and `projectOfHome("project~billing") = "billing"` (do not name it `projectIdOf`: the server's projects.ts already has a `projectIdOf` with another meaning). The project list comes from the existing hook `src/web/useProjects.ts` (entries `{ id, name, forge, workspaces: [{ id, fullPath, repo }] }`; repo names = `workspaces[].repo`).

### UPDATE `apps/graph-manager/src/web/pages/Runs.tsx`
- **IMPLEMENT**: in `RunRow`'s run cell, when `run.project`: `<span className="runs-project-chip" data-testid={\`run-project-${run.id}\`}>project · {run.project.name}</span>` and `<span className="runs-project-repos mono muted">{run.project.repos.join(", ")}</span>`. `GroupHeader` for a `project~` group: the same chip + repo names instead of forge chip/branch/clean pill; its "Open terminal" becomes a button that POSTs `/api/terminals { projectId }` and navigates to `/terminals?focus=<id>` (as `RunDetail.openTerminal`). The filter `<select>`: workspaces (ids without `project~`) first, then `<optgroup label="Projects">` with `project~<id>` options labelled by name, from `useProjects()` plus ids seen in runs. `repoName()` for the Failed card: project name for a project run. Add the chip styles in `Runs.css` with design tokens (look at `.runs-c-type.suite`).
